1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * The pinned region reference data used to derive an owner's locality. Knows both the
7	 * city-to-region table and each region's inclusive four-digit postcode range (NSW
8	 * 2000-2099, VIC 3000-3099, QLD 4000-4099).
9	 *
10	 * <p>Locality is derived by postcode first — {@link #localityOf(String, String)} looks up
11	 * the region whose range contains the postcode and only falls back to the city-to-region
12	 * table when the postcode is absent or in no known range. A city or postcode with no known
13	 * region resolves to {@link #UNKNOWN}.
14	 */
15	public final class CityRegion {
16	
17	    /** Locality returned when neither postcode nor city resolves to a known region. */
18	    public static final String UNKNOWN = "UNKNOWN";
19	
20	    private static final Map<String, String> CITY_TO_REGION = Map.of(
21	        "Sydney", "NSW",
22	        "Melbourne", "VIC",
23	        "Brisbane", "QLD");
24	
25	    /** Region -> inclusive {low, high} four-digit postcode range. */
26	    private static final Map<String, int[]> REGION_RANGES = Map.of(
27	        "NSW", new int[] {2000, 2099},
28	        "VIC", new int[] {3000, 3099},
29	        "QLD", new int[] {4000, 4099});
30	
31	    private CityRegion() {
32	    }
33	
34	    /**
35	     * The canonical region for the given city, or {@link #UNKNOWN} when the city is not
36	     * in the table (including a {@code null} city).
37	     */
38	    public static String localityOf(String city) {
39	        return CITY_TO_REGION.getOrDefault(city, UNKNOWN);
40	    }
41	
42	    /**
43	     * The canonical region, preferring the postcode: the region whose pinned range
44	     * contains {@code postcode}, falling back to the {@link #localityOf(String) city
45	     * table} when the postcode is absent or in no known range. This disambiguates cities
46	     * that share a name while still resolving known cities to the same region.
47	     */
48	    public static String localityOf(String postcode, String city) {
49	        String byPostcode = regionOfPostcode(postcode);
50	        return byPostcode != null ? byPostcode : localityOf(city);
51	    }
52	
53	    /**
54	     * The region whose pinned range contains {@code postcode}, or {@code null} when the
55	     * postcode is {@code null}, not four digits, or in no known range.
56	     */
57	    public static String regionOfPostcode(String postcode) {
58	        if (postcode == null || !postcode.matches("\\d{4}")) {
59	            return null;
60	        }
61	        int value = Integer.parseInt(postcode);
62	        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
63	            int[] range = entry.getValue();
64	            if (value >= range[0] && value <= range[1]) {
65	                return entry.getKey();
66	            }
67	        }
68	        return null;
69	    }
70	
71	    /**
72	     * The inclusive {low, high} four-digit postcode range pinned to {@code region}, or
73	     * {@code null} when the region has no pinned range.
74	     */
75	    public static int[] rangeOf(String region) {
76	        int[] range = REGION_RANGES.get(region);
77	        return range == null ? null : range.clone();
78	    }
79	}
