1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.CityRegion;
4	
5	/**
6	 * Postcode validity: a postcode must be exactly four digits, and when the owner's city has a
7	 * known region (see {@link CityRegion}) it must fall within that region's pinned inclusive
8	 * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
9	 * four-digit postcode.
10	 */
11	final class Postcodes {
12	
13	    private Postcodes() {
14	    }
15	
16	    /**
17	     * Whether {@code postcode} is valid for {@code city}: it must be exactly four digits and,
18	     * when the city's region has a pinned range, fall inside that range. Cities with no known
19	     * region accept any four-digit postcode.
20	     */
21	    static boolean isValidForCity(String postcode, String city) {
22	        if (postcode == null || !postcode.matches("\\d{4}")) {
23	            return false;
24	        }
25	        int[] range = CityRegion.rangeOf(CityRegion.localityOf(city));
26	        if (range == null) {
27	            return true;
28	        }
29	        int value = Integer.parseInt(postcode);
30	        return value >= range[0] && value <= range[1];
31	    }
32	}
