1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.AgeBand;
8	import org.springframework.samples.petclinic.model.CityRegion;
9	import org.springframework.samples.petclinic.model.ContactPreference;
10	import org.springframework.samples.petclinic.model.Luhn;
11	import org.springframework.samples.petclinic.model.MembershipLevel;
12	import org.springframework.samples.petclinic.model.Owner;
13	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
14	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
15	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
16	
17	import java.util.Collection;
18	import java.util.List;
19	
20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName",
27	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials", expression = "java(initials(owner))")
29	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
30	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
31	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
32	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
33	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
34	    @Mapping(target = "locality", expression = "java(locality(owner))")
35	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
36	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
37	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * The upper-cased first letters of the first and last name, dot-separated with a
42	     * trailing dot, e.g. {@code J.S.}.
43	     */
44	    default String initials(Owner owner) {
45	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
46	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
47	    }
48	
49	    /**
50	     * The owner's stored E.164 telephone number formatted for humans as the country code, a
51	     * space, then the national digits grouped in threes (e.g. {@code +61 412 345 678}). The
52	     * raw {@code telephone} field stays in E.164 form.
53	     */
54	    default String telephoneDisplay(Owner owner) {
55	        return org.springframework.samples.petclinic.rest.function.owner.Telephones
56	            .toDisplay(owner.getTelephone());
57	    }
58	
59	    /**
60	     * The Luhn check digit computed over the digits of the owner's customer code.
61	     */
62	    default int checkDigit(Owner owner) {
63	        return Luhn.checkDigit(owner.getCustomerCode());
64	    }
65	
66	    /**
67	     * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where
68	     * {@code YY} is the last two digits of the registration date year, e.g.
69	     * {@code SMI-0007-M26}.
70	     */
71	    default String membershipNumber(Owner owner) {
72	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
73	        return owner.getCustomerCode() + "-M" + yy;
74	    }
75	
76	    /**
77	     * The owner's membership points, as defined by {@link MembershipLevel}.
78	     */
79	    default int membershipPoints(Owner owner) {
80	        return MembershipLevel.points(owner);
81	    }
82	
83	    /**
84	     * The owner's membership level from 1 to 4, as defined by {@link MembershipLevel}.
85	     */
86	    default int membershipLevel(Owner owner) {
87	        return MembershipLevel.of(owner);
88	    }
89	
90	    /**
91	     * The region the owner's customer code was minted in — its {@code <REGION>} segment
92	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.CustomerCode}).
93	     * Owners without a customer code (e.g. legacy records) fall back to deriving the region
94	     * from the postcode and city directly.
95	     */
96	    default String locality(Owner owner) {
97	        String customerCode = owner.getCustomerCode();
98	        if (customerCode == null || customerCode.isBlank()) {
99	            return CityRegion.localityOf(owner.getPostcode(), owner.getCity());
100	        }
101	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCode
102	            .region(customerCode);
103	    }
104	
105	    /**
106	     * How the owner prefers to be contacted: {@code EMAIL} when an email address is
107	     * present, otherwise {@code PHONE}.
108	     */
109	    default String contactPreference(Owner owner) {
110	        return ContactPreference.of(owner).name();
111	    }
112	
113	    /**
114	     * The owner's age band derived from their birth date against their registration date
115	     * (see {@link AgeBand}), or {@code null} when no birth date was supplied.
116	     */
117	    default String ageBand(Owner owner) {
118	        AgeBand ageBand = AgeBand.of(owner);
119	        return ageBand == null ? null : ageBand.name();
120	    }
121	
122	    /**
123	     * The owner's derived identity key used for duplicate detection (see
124	     * {@link org.springframework.samples.petclinic.rest.function.owner.IdentityKeys}).
125	     */
126	    default String identityKey(Owner owner) {
127	        return org.springframework.samples.petclinic.rest.function.owner.IdentityKeys.of(owner);
128	    }
129	
130	    @Mapping(target = "householdMemberCount", ignore = true)
131	    Owner toOwner(OwnerDto ownerDto);
132	
133	    @Mapping(target = "id", ignore = true)
134	    @Mapping(target = "pets", ignore = true)
135	    @Mapping(target = "customerCode", ignore = true)
136	    @Mapping(target = "householdId", ignore = true)
137	    @Mapping(target = "namesakeCount", ignore = true)
138	    @Mapping(target = "householdMemberCount", ignore = true)
139	    Owner toOwner(OwnerFieldsDto ownerDto);
140	
141	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
142	
143	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
144	
145	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
146	        OwnerPageDto ownerPageDto = new OwnerPageDto();
147	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
148	        ownerPageDto.setPage(ownerPage.getNumber());
149	        ownerPageDto.setSize(ownerPage.getSize());
150	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
151	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
152	        return ownerPageDto;
153	    }
154	}
